const raw = $input.first().json.text || ($input.first().json.content?.[0]?.text);
const match = raw.match(/\{[\s\S]*\}/);
if (!match) throw new Error('No JSON from Claude: ' + raw.substring(0, 300));
const ai = JSON.parse(match[0]);

const file = $('Get Latest Video from Drive').item.json;
if (!file || !file.id) throw new Error('No video found in Drive folder. Returned: ' + JSON.stringify(file).substring(0, 200));

const nameNoExt = (file.name || '').replace(/\.(mp4|mov|avi|mkv|webm)$/i, '');
const topic = nameNoExt.split(' - ')[0] || nameNoExt;
const postText = ai.title + '\n\n' + ai.caption + '\n\n' + ai.hashtags;

return [{ json: {
  fileId: file.id,
  filename: file.name,
  topic: topic,
  Title: ai.title,
  Caption: ai.caption,
  Hashtags: ai.hashtags,
  postText: postText
} }];

// Extract session cookie from Odoo auth response
const response = $input.first();
const headers = response.json.headers || {};

// Get Set-Cookie header
const setCookie = response.json.headers?.['set-cookie'];
let sessionCookie = '';
if (setCookie) {
  const cookies = Array.isArray(setCookie) ? setCookie : [setCookie];
  const sessionMatch = cookies.find(c => c.includes('session_id'));
  if (sessionMatch) {
    sessionCookie = sessionMatch.split(';')[0]; // e.g. session_id=abc123
  }
}

// Also get uid from body
const body = response.json.body || response.json;
const uid = body?.result?.uid;

if (!uid) throw new Error('Odoo auth failed. Check credentials. Response: ' + JSON.stringify(body).substring(0, 300));

// Pass through all previous data plus session info
const postData = $('Build Post Data').item.json;
const videoUrl = $('Upload Video to Public Host').item.json.publicUrl;

return [{ json: {
  sessionCookie: sessionCookie,
  uid: uid,
  postText: postData.postText,
  Title: postData.Title,
  videoUrl: videoUrl,
  filename: postData.filename
} }];

// Find account IDs for Long Island Convenience website
// Social accounts linked to the LI website in Odoo
const response = $input.first().json;
const accounts = response?.result || [];

console.log('All social accounts:', JSON.stringify(accounts));

// Filter accounts for Long Island Convenience website
// website_id[1] is the website name — adjust if needed
const liAccounts = accounts.filter(a => 
  a.website_id && (
    a.website_id[1]?.toLowerCase().includes('long island') ||
    a.website_id[1]?.toLowerCase().includes('country cove')
  )
);

const accountIds = liAccounts.length > 0 
  ? liAccounts.map(a => a.id)
  : accounts.map(a => a.id); // fallback: use all accounts

if (accountIds.length === 0) {
  throw new Error('No social accounts found in Odoo. Connect Facebook/Instagram in Social Marketing first.');
}

console.log('Posting to account IDs:', accountIds);

const prev = $('Extract Odoo Session').item.json;

// Build message with video link appended
const fullMessage = prev.postText + '\n\n▶️ Watch: ' + prev.videoUrl;

return [{ json: {
  sessionCookie: prev.sessionCookie,
  accountIds: accountIds,
  message: fullMessage,
  videoUrl: prev.videoUrl,
  Title: prev.Title
} }];

const response = $input.first().json;
const postId = response?.result;
if (!postId || typeof postId !== 'number') {
  throw new Error('Failed to create Odoo social post. Response: ' + JSON.stringify(response).substring(0, 300));
}
console.log('Created Odoo social post ID:', postId);
const prev = $('Filter LI Accounts').item.json;
return [{ json: { sessionCookie: prev.sessionCookie, postId: postId } }];

const response = $input.first().json;
const postId = $('Get Post ID').item.json.postId;
console.log('Publish response:', JSON.stringify(response));
return [{ json: {
  status: 'SUCCESS',
  postId: postId,
  odooPostUrl: 'https://country-cove-inc.odoo.com/web#model=social.post&id=' + postId,
  message: 'Post published via Odoo Social Marketing for Long Island Convenience',
  timestamp: new Date().toISOString()
} }];
